begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create function pg_temp.id(n integer)returns uuid language sql immutable as $$select('ae290000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
select ok(not exists(select 1 from public.doctor_administration_nonces),'no nonce or binding seeded');
select ok(not exists(select 1 from public.doctor_administration_audit),'no administration approval or audit seeded');
select ok(doctor_private.consume_administration_nonce(pg_temp.id(1),'synthetic-v1',pg_temp.id(2),pg_temp.id(3),clock_timestamp()+interval'2 minutes'),'first nonce accepted by fixture owner');
select ok(not doctor_private.consume_administration_nonce(pg_temp.id(1),'synthetic-v1',pg_temp.id(2),pg_temp.id(3),clock_timestamp()+interval'2 minutes'),'exact nonce replay denied');
select ok(not doctor_private.consume_administration_nonce(pg_temp.id(1),'synthetic-v1',pg_temp.id(2),pg_temp.id(4),clock_timestamp()+interval'2 minutes'),'changed request cannot reuse nonce');
select ok(doctor_private.consume_administration_nonce(pg_temp.id(5),'synthetic-v1',pg_temp.id(2),pg_temp.id(3),clock_timestamp()+interval'2 minutes'),'source environment binding scopes nonce identity');
select ok(doctor_private.consume_administration_nonce(pg_temp.id(1),'synthetic-v2',pg_temp.id(2),pg_temp.id(3),clock_timestamp()+interval'2 minutes'),'explicit different key scopes nonce identity');
select throws_ok($$select doctor_private.consume_administration_nonce(pg_temp.id(1),'synthetic-v1',pg_temp.id(6),pg_temp.id(3),clock_timestamp()-interval'1 second')$$,'22023','DOCTOR_ADMIN_NONCE_INVALID','expired nonce rejected');
create function pg_temp.audit(nonce integer,request integer)returns jsonb language sql as $$select jsonb_build_object('sourceBindingId',pg_temp.id(1),'targetBindingId',pg_temp.id(7),'targetEnvironmentId',pg_temp.id(8),'authorityBindingId',pg_temp.id(9),'subjectId',pg_temp.id(10),'roleSnapshot','SYNTHETIC_OPERATOR_ROLE','keyId','synthetic-v1','nonce',pg_temp.id(nonce),'requestId',pg_temp.id(request),'correlationId',pg_temp.id(11),'operation','doctor.plan.query','requestDigest',repeat('a',64),'responseDigest',repeat('b',64),'manifestDigest',repeat('c',64),'outcome','synthetic_read')$$;
select ok(doctor_private.append_administration_audit(pg_temp.audit(2,3))is not null,'audit binds consumed nonce and exact request');
select throws_ok($$select doctor_private.append_administration_audit(pg_temp.audit(2,4))$$,'42501','DOCTOR_ADMIN_RECEIPT_REQUIRED','audit cannot reassign consumed nonce to different request');
select throws_ok($$select doctor_private.append_administration_audit(pg_temp.audit(6,3))$$,'42501','DOCTOR_ADMIN_RECEIPT_REQUIRED','audit without consumed nonce denied');
select throws_ok($$select doctor_private.append_administration_audit(pg_temp.audit(2,3)||jsonb_build_object('payload','synthetic private payload'))$$,'22023','DOCTOR_ADMIN_AUDIT_INVALID','audit rejects raw payload fields');
select throws_ok($$select doctor_private.append_administration_audit(pg_temp.audit(2,3)||jsonb_build_object('signature','synthetic-signature'))$$,'22023','DOCTOR_ADMIN_AUDIT_INVALID','audit rejects signatures or credential fields');
select throws_ok($$update public.doctor_administration_audit set role_snapshot='owner'$$,'42501','DOCTOR_SAAS_HISTORY_IMMUTABLE','actor audit cannot be rewritten');
select throws_ok($$delete from public.doctor_administration_nonces$$,'42501','DOCTOR_SAAS_HISTORY_IMMUTABLE','nonce receipts retained after domain denial');
select throws_ok($$truncate public.doctor_administration_nonces cascade$$,'42501','DOCTOR_SAAS_HISTORY_IMMUTABLE','receipt/audit history cannot truncate');
select ok(not has_table_privilege(role_name,'public.'||table_name,'select,insert,update,delete,truncate'),'no raw '||role_name||' access to '||table_name)
 from unnest(array['anon','authenticated','service_role'])role_name cross join unnest(array['doctor_administration_nonces','doctor_administration_audit'])table_name;
select ok(not has_function_privilege(role_name,'doctor_private.consume_administration_nonce(uuid,text,uuid,uuid,timestamptz)','execute'),'no client nonce insertion: '||role_name)from unnest(array['anon','authenticated','service_role'])role_name;
select ok(not has_function_privilege(role_name,'doctor_private.append_administration_audit(jsonb)','execute'),'no client audit forgery: '||role_name)from unnest(array['anon','authenticated','service_role'])role_name;
insert into auth.users(id,email,email_confirmed_at)values(pg_temp.id(21),'synthetic-admin-readiness@example.test',now());
insert into auth.sessions(id,user_id)values(pg_temp.id(22),pg_temp.id(21));
set local role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.id(21),'session_id',pg_temp.id(22),'role','authenticated','user_metadata',jsonb_build_object('operator',true,'paid',true))::text,true);
select is(public.doctor_administration_readiness()->>'state','unavailable','missing target integration remains unavailable');
select is(public.doctor_administration_readiness()->>'target_binding','unconfigured','no target environment is guessed');
select is(public.doctor_administration_readiness()->>'signing','unconfigured','no signing credential is created or borrowed');
select is(public.doctor_administration_readiness()->>'operator_grant_available','false','editable metadata cannot grant operator activation');
select is(public.doctor_administration_readiness()->>'payment_confirmed','false','operator grant is distinct from payment confirmation');
select is(public.doctor_administration_readiness()->>'live_activation','false','clinical/live gates remain closed');
reset role;
select * from finish();rollback;
